-- Rollback fixtures only. No actual anonymous sign-in or account is created.
begin;
-- Live membership can grow between releases. Never rewind numbers belonging to real users.
create temp table guest_sequence_baseline as select last_value from public.member_number_seq;
create temp table t_res(n serial,name text,ok boolean,detail text) on commit drop;
grant all on t_res to authenticated,anon,service_role;grant usage on sequence t_res_n_seq to authenticated,anon,service_role;
create function pg_temp.t(p_name text,p_user uuid,p_sql text,p_expect text,p_path text default '') returns void language plpgsql as $$declare v text;begin begin
 perform set_config('request.jwt.claims',jsonb_build_object('sub',p_user,'role','authenticated','is_anonymous',false)::text,true);
 perform set_config('request.path',p_path,true);set local role authenticated;
 if p_path<>'' then perform public.check_account_request();end if;
 execute p_sql into v;reset role;perform set_config('request.jwt.claims','',true);
 insert into t_res(name,ok,detail)values(p_name,p_expect='ok' or(p_expect like '=%' and v is not distinct from substr(p_expect,2)),coalesce(v,'null'));
 exception when others then reset role;perform set_config('request.jwt.claims','',true);insert into t_res(name,ok,detail)values(p_name,p_expect<>'ok' and p_expect not like '=%' and sqlerrm ilike '%'||p_expect||'%',sqlerrm);end;end $$;
insert into auth.users(id,email,aud,role,is_anonymous,raw_user_meta_data)values
 ('00000000-0000-4000-8000-0000000000b1',null,'authenticated','authenticated',true,'{"username":"rayvn","display_name":"rayvn","is_anonymous":false,"is_guest":false,"country":"DE"}'),
 ('00000000-0000-4000-8000-0000000000b2',null,'authenticated','authenticated',true,'{"display_name":"Second guest"}');
alter table public.profiles alter column member_number set default 900000003;
insert into auth.users(id,email,aud,role,raw_user_meta_data)values('00000000-0000-4000-8000-0000000000b3','zz-guest-owner@onyx.invalid','authenticated','authenticated','{"username":"zz_guest_owner"}');
alter table public.profiles alter column member_number set default nextval('public.member_number_seq');
insert into public.servers(id,name,owner_id)values('16161616-1616-4161-8161-161616161601','Guest scope fixture','00000000-0000-4000-8000-0000000000b3');
insert into public.roles(id,server_id,name,permissions,is_default)values('16161616-1616-4161-8161-161616161603','16161616-1616-4161-8161-161616161601','@everyone',enum_range(null::public.permission),true);
insert into public.server_members(server_id,user_id)values('16161616-1616-4161-8161-161616161601','00000000-0000-4000-8000-0000000000b3');
insert into public.channels(id,server_id,name)values('16161616-1616-4161-8161-161616161602','16161616-1616-4161-8161-161616161601','general');
insert into public.channels(id,server_id,name,type)values('16161616-1616-4161-8161-161616161604','16161616-1616-4161-8161-161616161601','Lobby','voice');
insert into public.invites(code,server_id,inviter_id)values('zz-guest-invite','16161616-1616-4161-8161-161616161601','00000000-0000-4000-8000-0000000000b3');
select pg_temp.t('Guest profile uses real Auth state despite forged metadata','00000000-0000-4000-8000-0000000000b1',$q$select is_guest::text from public.profiles where id='00000000-0000-4000-8000-0000000000b1'$q$,'=true','');
select pg_temp.t('Guest display name is kept, internal username cannot squat rayvn','00000000-0000-4000-8000-0000000000b1',$q$select (display_name='rayvn' and username like 'guest.%' and username<>'rayvn')::text from public.profiles where id='00000000-0000-4000-8000-0000000000b1'$q$,'=true','');
select pg_temp.t('Guests have no member number, country or earned cosmetics','00000000-0000-4000-8000-0000000000b1',$q$select (member_number is null and country is null and cardinality(badges)=0)::text from public.profiles where id='00000000-0000-4000-8000-0000000000b1'$q$,'=true','');
select pg_temp.t('Official server includes guests','00000000-0000-4000-8000-0000000000b1',$q$select (public.ensure_official_server() is not null)::text$q$,'=true','/rpc/ensure_official_server');
select pg_temp.t('Guest joins a normal server through a valid invitation','00000000-0000-4000-8000-0000000000b1',$q$select (public.join_server_by_invite('zz-guest-invite')='16161616-1616-4161-8161-161616161601')::text$q$,'=true','/rpc/join_server_by_invite');
select pg_temp.t('Native channel read/write permissions remain','00000000-0000-4000-8000-0000000000b1',$q$select ('sendMessages'=any(private.channel_permissions('16161616-1616-4161-8161-161616161602')))::text$q$,'=true','');
select pg_temp.t('Even an admin role cannot give guests management rights','00000000-0000-4000-8000-0000000000b1',$q$select (not ('administrator'=any(private.channel_permissions('16161616-1616-4161-8161-161616161602'))) and not ('manageServer'=any(private.server_permissions('16161616-1616-4161-8161-161616161601'))))::text$q$,'=true','');
select pg_temp.t('Guests cannot upload attachments through channel rights','00000000-0000-4000-8000-0000000000b1',$q$select (not ('attachFiles'=any(private.channel_permissions('16161616-1616-4161-8161-161616161602'))))::text$q$,'=true','');
select pg_temp.t('Guest may enter server voice with microphone, video and screen rights','00000000-0000-4000-8000-0000000000b1',$q$select ((public.voice_join_check('16161616-1616-4161-8161-161616161604')->>'can_speak')::boolean and (public.voice_join_check('16161616-1616-4161-8161-161616161604')->>'can_video')::boolean)::text$q$,'=true','/rpc/voice_join_check');
select pg_temp.t('Guest cannot moderate a call despite an admin role','00000000-0000-4000-8000-0000000000b1',$q$select public.voice_moderate('16161616-1616-4161-8161-161616161604','00000000-0000-4000-8000-0000000000b3','mute',true)$q$,'registration_required','/rpc/voice_moderate');
select pg_temp.t('Guest cannot receive server ownership','00000000-0000-4000-8000-0000000000b3',$q$select public.transfer_server_ownership('16161616-1616-4161-8161-161616161601','00000000-0000-4000-8000-0000000000b1')$q$,'registered owner required','');
select pg_temp.t('Guest sends a real channel text message','00000000-0000-4000-8000-0000000000b1',$q$insert into public.messages(channel_id,author_id,content) values('16161616-1616-4161-8161-161616161602','00000000-0000-4000-8000-0000000000b1','Hello from a guest') returning (content='Hello from a guest')::text$q$,'=true','');
select pg_temp.t('Guest cannot upload a forged attachment','00000000-0000-4000-8000-0000000000b1',$q$insert into public.messages(channel_id,author_id,content,attachments) values('16161616-1616-4161-8161-161616161602','00000000-0000-4000-8000-0000000000b1','Attachment','[{"path":"fake"}]') returning id$q$,'registration_required','');
select pg_temp.t('Guest cannot set a profile bio','00000000-0000-4000-8000-0000000000b1',$q$update public.profiles set bio='forged' where id='00000000-0000-4000-8000-0000000000b1' returning id$q$,'registration_required','');
select pg_temp.t('Guest cannot set a profile color','00000000-0000-4000-8000-0000000000b1',$q$update public.profiles set avatar_color='#ffffff' where id='00000000-0000-4000-8000-0000000000b1' returning id$q$,'registration_required','');
select pg_temp.t('Guest cannot choose another display name','00000000-0000-4000-8000-0000000000b1',$q$update public.profiles set display_name='Impersonation' where id='00000000-0000-4000-8000-0000000000b1' returning id$q$,'registration_required','');
select pg_temp.t('Guest marker is protected by column privileges','00000000-0000-4000-8000-0000000000b1',$q$update public.profiles set is_guest=false where id='00000000-0000-4000-8000-0000000000b1' returning id$q$,'permission denied','');
select pg_temp.t('Guest can publish automatic presence','00000000-0000-4000-8000-0000000000b1',$q$update public.profiles set status='idle' where id='00000000-0000-4000-8000-0000000000b1' returning (status='idle')::text$q$,'=true','');
select pg_temp.t('Guest server creation RPC is blocked even without API hook','00000000-0000-4000-8000-0000000000b1',$q$select public.create_server('{}')$q$,'registration_required','');
select pg_temp.t('Guest DM creation is blocked even without API hook','00000000-0000-4000-8000-0000000000b1',$q$select public.open_dm('00000000-0000-4000-8000-0000000000b3')$q$,'registration_required','');
select pg_temp.t('Permanent accounts cannot start DMs with guests','00000000-0000-4000-8000-0000000000b3',$q$select public.open_dm('00000000-0000-4000-8000-0000000000b1')$q$,'guest_direct_messages_unavailable','');
select pg_temp.t('Guest friend request cannot bypass UI','00000000-0000-4000-8000-0000000000b1',$q$select public.friend_request('zz_guest_owner')$q$,'registration_required','');
select pg_temp.t('Permanent accounts cannot send a guest a friend request','00000000-0000-4000-8000-0000000000b3',$q$select (public.friend_request((select username from public.profiles where id='00000000-0000-4000-8000-0000000000b1'))->>'status'='unavailable')::text$q$,'=true','');
select pg_temp.t('SQL-language friend RPC is guarded','00000000-0000-4000-8000-0000000000b1',$q$select public.friend_accept('00000000-0000-4000-8000-0000000000b3')$q$,'registration_required','');
select pg_temp.t('Guest role editing API route is blocked','00000000-0000-4000-8000-0000000000b1',$q$select true$q$,'registration_required','/rpc/replace_overwrites');
select pg_temp.t('Guest developer API route is blocked','00000000-0000-4000-8000-0000000000b1',$q$select true$q$,'registration_required','/rpc/bot_pair_start');
select pg_temp.t('Guest connection API route is blocked','00000000-0000-4000-8000-0000000000b1',$q$select true$q$,'registration_required','/rpc/social_start');
select pg_temp.t('Guest reward API route is blocked','00000000-0000-4000-8000-0000000000b1',$q$select true$q$,'registration_required','/rpc/redeem_code');
select pg_temp.t('Guest cannot store private profile notes','00000000-0000-4000-8000-0000000000b1',$q$insert into public.user_notes(owner_id,target_id,note) values('00000000-0000-4000-8000-0000000000b1','00000000-0000-4000-8000-0000000000b3','test') returning owner_id$q$,'row-level security','');
select pg_temp.t('Guest can block another user','00000000-0000-4000-8000-0000000000b1',$q$select public.user_block('00000000-0000-4000-8000-0000000000b3')$q$,'ok','/rpc/user_block');
select pg_temp.t('Guest can unblock again','00000000-0000-4000-8000-0000000000b1',$q$select public.friend_remove('00000000-0000-4000-8000-0000000000b3')$q$,'ok','/rpc/friend_remove');
select pg_temp.t('Guest cannot claim a permanent username before email verification','00000000-0000-4000-8000-0000000000b1',$q$select public.complete_guest_registration('zz_new_member','DE')$q$,'guest_email_verification_required','/rpc/complete_guest_registration');
select pg_temp.t('Guest namespace is unavailable to ordinary registration','00000000-0000-4000-8000-0000000000b3',$q$select (not public.username_available('guest.reserved'))::text$q$,'=true','');
insert into t_res(name,ok) select 'Guest sign-ins do not advance member sequence',s.last_value=b.last_value from public.member_number_seq s cross join guest_sequence_baseline b;
insert into t_res(name,ok) select 'Guest referrals do not farm invite rewards',not exists(select 1 from private.invite_joins where joiner_id='00000000-0000-4000-8000-0000000000b1');
-- Isolate the non-transactional allocator. This helper replacement is itself rolled back.
create temp sequence guest_member_test_seq start 50;
create or replace function private.allocate_member_number() returns bigint language sql volatile security definer set search_path='' as $$select nextval('pg_temp.guest_member_test_seq')$$;
update auth.users set is_anonymous=false,email='zz-guest-converted@onyx.invalid',email_confirmed_at=now() where id='00000000-0000-4000-8000-0000000000b1';
select pg_temp.t('Verified email alone does not finish password registration','00000000-0000-4000-8000-0000000000b1',$q$select public.complete_guest_registration('zz_new_member','DE')$q$,'guest_email_verification_required','');
update auth.users set encrypted_password='synthetic-hash-never-used-for-auth' where id='00000000-0000-4000-8000-0000000000b1';
select pg_temp.t('Country cannot be bypassed via the old conversion signature','00000000-0000-4000-8000-0000000000b1',$q$select public.complete_guest_registration('zz_new_member')$q$,'country_required','');
select pg_temp.t('Conversion still requires a valid, available username','00000000-0000-4000-8000-0000000000b1',$q$select public.complete_guest_registration('rayvn','DE')$q$,'username unavailable','');
select pg_temp.t('Conversion keeps the same user and succeeds','00000000-0000-4000-8000-0000000000b1',$q$select public.complete_guest_registration('zz_new_member','DE')$q$,'ok','');
select pg_temp.t('Converted profile is permanent with member number and first badge','00000000-0000-4000-8000-0000000000b1',$q$select (not is_guest and username='zz_new_member' and member_number=50 and 'first-100'=any(badges))::text from public.profiles where id='00000000-0000-4000-8000-0000000000b1'$q$,'=true','');
select pg_temp.t('Conversion keeps server membership and message authorship','00000000-0000-4000-8000-0000000000b1',$q$select (exists(select 1 from public.server_members where user_id='00000000-0000-4000-8000-0000000000b1' and server_id='16161616-1616-4161-8161-161616161601') and exists(select 1 from public.messages where author_id='00000000-0000-4000-8000-0000000000b1' and content='Hello from a guest'))::text$q$,'=true','');
select pg_temp.t('Conversion retry does not allocate another number','00000000-0000-4000-8000-0000000000b1',$q$select public.complete_guest_registration('zz_different_name')$q$,'ok','');
select pg_temp.t('Permanent profile can now use customization','00000000-0000-4000-8000-0000000000b1',$q$update public.profiles set bio='My permanent profile' where id='00000000-0000-4000-8000-0000000000b1' returning (bio='My permanent profile')::text$q$,'=true','');
select pg_temp.t('Permanent channel rights return after conversion','00000000-0000-4000-8000-0000000000b1',$q$select ('manageServer'=any(private.server_permissions('16161616-1616-4161-8161-161616161601')))::text$q$,'=true','');
select pg_temp.t('Guest cannot remove official membership','00000000-0000-4000-8000-0000000000b2',$q$delete from public.server_members where user_id='00000000-0000-4000-8000-0000000000b2' and server_id=public.ensure_official_server() returning user_id$q$,'official community','');
select pg_temp.t('Another guest may join an ordinary server','00000000-0000-4000-8000-0000000000b2',$q$select (public.join_server_by_invite('zz-guest-invite')='16161616-1616-4161-8161-161616161601')::text$q$,'=true','');
select pg_temp.t('Guest may leave an ordinary server','00000000-0000-4000-8000-0000000000b2',$q$with removed as(delete from public.server_members where user_id='00000000-0000-4000-8000-0000000000b2' and server_id='16161616-1616-4161-8161-161616161601' returning *)select (count(*)=1)::text from removed$q$,'=true','');
insert into t_res(name,ok)select 'Guests cannot receive earned badges',not private.grant_badge('00000000-0000-4000-8000-0000000000b2','bug-hunter');
insert into t_res(name,ok)select 'The sequence allocator is not callable by clients',not has_function_privilege('authenticated','private.allocate_member_number()','execute');
insert into t_res(name,ok)select 'Guest Storage upload policy is restrictive',exists(select 1 from pg_policies where schemaname='storage' and policyname='onyx: registered upload' and permissive='RESTRICTIVE');
select count(*) total,count(*)filter(where ok)passed,jsonb_agg(jsonb_build_object('name',name,'detail',detail))filter(where not ok)failed from t_res;
rollback;
